<?php if(!$admin): ?>
<script>
(() => {
  const grid = document.getElementById('overview-cards');
  const form = document.getElementById('overview-layout-form');
  if (!grid || !form) return;
  const defaultOrder = <?= json_encode($defaultOverviewOrder, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;
  const savedOrder = <?= json_encode($overviewOrder, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;
  const getCards = () => [...grid.querySelectorAll('[data-overview-card]')];
  const applyOrder = (keys) => {
    const byKey = new Map(getCards().map(card => [card.dataset.overviewCard, card]));
    for (const key of keys) if (byKey.has(key)) grid.appendChild(byKey.get(key));
    for (const card of getCards()) grid.appendChild(card);
  };
  applyOrder(savedOrder);
  let dragged = null;
  for (const card of getCards()) {
    const heading = card.querySelector('.card-title');
    if (!heading) continue;
    const handle = document.createElement('button');
    handle.type = 'button';
    handle.className = 'drag-handle';
    handle.textContent = '↕';
    handle.draggable = true;
    handle.setAttribute('aria-label', 'Karte verschieben');
    handle.title = 'Ziehen oder mit den Pfeiltasten verschieben';
    handle.addEventListener('dragstart', event => {
      dragged = card;
      card.classList.add('is-dragging');
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', card.dataset.overviewCard);
    });
    handle.addEventListener('dragend', () => {
      card.classList.remove('is-dragging');
      dragged = null;
    });
    handle.addEventListener('keydown', event => {
      if (event.key !== 'ArrowUp' && event.key !== 'ArrowDown') return;
      event.preventDefault();
      const cards = getCards();
      const position = cards.indexOf(card);
      const target = cards[position + (event.key === 'ArrowUp' ? -1 : 1)];
      if (!target) return;
      if (event.key === 'ArrowUp') grid.insertBefore(card, target);
      else grid.insertBefore(target, card);
      handle.focus();
    });
    const moveControls = document.createElement('span');
    moveControls.className = 'layout-move-controls';
    for (const [label, delta] of [['↑', -1], ['↓', 1]]) {
      const moveButton = document.createElement('button');
      moveButton.type = 'button';
      moveButton.className = 'drag-handle';
      moveButton.textContent = label;
      moveButton.setAttribute('aria-label', delta < 0 ? 'Karte nach oben verschieben' : 'Karte nach unten verschieben');
      moveButton.addEventListener('click', () => {
        const cards = getCards();
        const position = cards.indexOf(card);
        const target = cards[position + delta];
        if (!target) return;
        if (delta < 0) grid.insertBefore(card, target);
        else grid.insertBefore(target, card);
        moveButton.focus();
      });
      moveControls.appendChild(moveButton);
    }
    heading.appendChild(moveControls);
    heading.appendChild(handle);
  }
  grid.addEventListener('dragover', event => {
    if (!dragged) return;
    event.preventDefault();
    const target = event.target.closest('[data-overview-card]');
    if (!target || target === dragged) return;
    const rect = target.getBoundingClientRect();
    grid.insertBefore(dragged, event.clientY < rect.top + rect.height / 2 ? target : target.nextSibling);
  });
  grid.addEventListener('drop', event => {
    if (dragged) event.preventDefault();
  });
  document.getElementById('overview-layout-reset')?.addEventListener('click', () => applyOrder(defaultOrder));
  form.addEventListener('submit', () => {
    document.getElementById('overview-layout-order').value = JSON.stringify(getCards().map(card => card.dataset.overviewCard));
  });
})();
</script>
<?php endif; ?>
</body></html>